def transform(grid):
    h=len(grid); w=len(grid[0])
    seen=set(); comps=0
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=0 and (i,j) not in seen:
                comps+=1
                stack=[(i,j)]; seen.add((i,j))
                while stack:
                    x,y=stack.pop()
                    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                        nx,ny=x+dx,y+dy
                        if 0<=nx<h and 0<=ny<w and grid[nx][ny]!=0 and (nx,ny) not in seen:
                            seen.add((nx,ny)); stack.append((nx,ny))
    return [[0]*comps]
